#!/usr/bin/env python3
"""AssignHub Quiz Engine PART 1: class-first, course-first, secure server grading.
Run `python apply_assignhub_quizzes_class_first.py --check` first, then `--apply`.
No third-party dependencies or network access required.
"""
import argparse
import base64
import datetime
import json
import shutil
import sys
import zlib
from pathlib import Path

PACKED = """"""
OLD_PACKED = """"""
FILES = json.loads(zlib.decompress(base64.b64decode(PACKED)).decode('utf-8'))
OLD_FILES = json.loads(zlib.decompress(base64.b64decode(OLD_PACKED)).decode('utf-8'))
ROOT = Path(__file__).resolve().parent


def patch_files():
    changes = {}
    settings_path = ROOT / 'config' / 'settings.py'
    urls_path = ROOT / 'config' / 'urls.py'
    base_path = ROOT / 'templates' / 'base.html'
    for p in (settings_path, urls_path, base_path):
        if not p.is_file():
            raise RuntimeError(f'Missing AssignHub baseline: {p.relative_to(ROOT)}')

    source = settings_path.read_text(encoding='utf-8')
    new = source
    if '"quizzes.apps.QuizzesConfig"' not in source:
        anchor = '"notifications.apps.NotificationsConfig",'
        if source.count(anchor) != 1:
            raise RuntimeError('Expected notifications app anchor not found in config/settings.py; no changes made.')
        new = source.replace(anchor, anchor + '\n    "quizzes.apps.QuizzesConfig",', 1)
    if new != source: changes[settings_path] = new

    source = urls_path.read_text(encoding='utf-8')
    new = source
    if 'include("quizzes.urls")' not in source:
        anchor = 'path("notifications/", include("notifications.urls")),'
        if source.count(anchor) != 1:
            raise RuntimeError('Expected notifications URL anchor not found in config/urls.py; no changes made.')
        new = source.replace(anchor, anchor + '\n    path("quizzes/", include("quizzes.urls")),', 1)
    if new != source: changes[urls_path] = new

    source = base_path.read_text(encoding='utf-8')
    new = source
    css_anchor = "<link rel=\"stylesheet\" href=\"{% static 'css/notifications.css' %}\">"
    if "static 'css/quizzes.css'" not in new:
        if new.count(css_anchor) != 1:
            raise RuntimeError('Expected CSS anchor not found in templates/base.html; no changes made.')
        new = new.replace(css_anchor, css_anchor + "\n    <link rel=\"stylesheet\" href=\"{% static 'css/quizzes.css' %}\">", 1)

    nav_marker = '<!-- ASSIGNHUB QUIZ MODULE LINK -->'
    if nav_marker not in new:
        anchor = 'href="{% url ' + chr(39) + 'assignments:list' + chr(39) + ' %}"'
        start = new.find(anchor)
        if start < 0:
            raise RuntimeError('Expected sidebar Assignments link not found in templates/base.html.')
        end = new.find('</a>', start)
        if end < 0:
            raise RuntimeError('Assignments sidebar link is malformed in templates/base.html.')
        end += len('</a>')
        quiz_nav = """

                <!-- ASSIGNHUB QUIZ MODULE LINK -->
                <a href="{% url 'quizzes:list' %}"
                   class="ah-sidebar-link {% if request.resolver_match.namespace == 'quizzes' %}active{% endif %}"
                   title="Quizzes">
                  <span class="ah-sidebar-link-icon"><i class="bi bi-ui-checks" aria-hidden="true"></i></span>
                  <span class="ah-sidebar-link-label">Quizzes</span>
                </a>"""
        new = new[:end] + quiz_nav + new[end:]
    if new != source: changes[base_path] = new
    return changes


def main():
    parser=argparse.ArgumentParser(description='Install/update Quiz Engine Part 1 without modifying existing workflows.')
    group=parser.add_mutually_exclusive_group(required=True)
    group.add_argument('--check',action='store_true',help='Dry-run only; show planned changes')
    group.add_argument('--apply',action='store_true',help='Install the new app and three additive config/template edits')
    args=parser.parse_args()
    if not (ROOT / 'manage.py').is_file() or not (ROOT / 'courses' / 'models.py').is_file():
        sys.exit('ERROR: Place this installer in AssignHub project root beside manage.py.')
    try:
        patches=patch_files()  # validate ALL three integration points before touching disk
        writes={}
        replacements={}
        for rel, content in FILES.items():
            path=ROOT / rel
            if not path.resolve().is_relative_to(ROOT.resolve()):
                raise RuntimeError('Unsafe packaged file path: '+rel)
            if path.is_file():
                current=path.read_text(encoding='utf-8')
                if current != content:
                    if rel not in OLD_FILES or current != OLD_FILES[rel]:
                        raise RuntimeError(f'Refusing to overwrite customized quiz file: {rel}')
                    replacements[path]=content
            elif path.exists():
                raise RuntimeError('A non-file path blocks quiz installation: '+rel)
            else:
                writes[path]=content
        print('AssignHub Quiz Module — '+('DRY-RUN' if args.check else 'INSTALL'))
        print('New files:',len(writes),'| Existing files to patch:',len(patches),'| V1 files to upgrade:',len(replacements))
        for path in writes: print('  ADD',path.relative_to(ROOT))
        for path in patches: print('  PATCH',path.relative_to(ROOT))
        for path in replacements: print('  UPGRADE',path.relative_to(ROOT))
        if args.check:
            print('No files changed. Run --apply when ready.')
            return
        if patches or replacements:
            timestamp=datetime.datetime.now().strftime('%Y%m%d_%H%M%S_%f')
            backdir=ROOT.parent / 'AssignHub_Quiz_Backups' / timestamp
            for path in {**patches, **replacements}:
                backup=backdir / path.relative_to(ROOT)
                backup.parent.mkdir(parents=True,exist_ok=True)
                shutil.copy2(path,backup)
            print('Backups:',backdir)
        for path, content in writes.items():
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content,encoding='utf-8')
        for path, content in {**replacements, **patches}.items():
            path.write_text(content,encoding='utf-8')
        print('Quiz Engine Part 1 installed. Now run:')
        print('  python manage.py makemigrations quizzes')
        print('  python manage.py migrate')
        print('  python manage.py check')
        print('  python manage.py test quizzes')
        print('  python manage.py runserver')
        print('Browser: http://127.0.0.1:8000/quizzes/')
    except Exception as exc:
        sys.exit('INSTALL ABORTED: '+str(exc))


if __name__ == '__main__':
    main()
